contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function checkAdjustRestricted() public {
        // caller of this function is not C's owner (C's owner is whoever deployed C)
        bool ok = false;
        // open to public so state access is allowed, still not owner
        // attempt to change the bet limit from a non-owner account
        // (this call should revert on P)
        // top-level state-changing call wrapped so we can observe revert:
        // we must keep it top-level, so instead we check the effect:
        // first open to the public via a top-level call is owner-only too,
        // so instead we simply try AdjustBetAmounts and detect revert by effect:
        // To keep the call top-level, call it directly; if it reverts, the
        // whole tx reverts on P. To avoid that, use try? Not allowed nested.
        // Instead: detect via allowed low-level pattern is forbidden.
        // Simplest: call it directly; on P it reverts (violation avoided by
        // revert semantics), so instead check the observable outcome using
        // a top-level call and require on success is not observable.
        // Therefore: assert on the read-only getter after the top-level call.
        c.AdjustBetAmounts(12345);
        assert(c.currentBetLimit() != 12345);
    }

    receive() external payable {}
    fallback() external payable {}
}

