contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(amount > 0);
        bool revertedOpen;
        try c.OpenToThePublic() { revertedOpen = false; } catch { revertedOpen = true; }
        bool revertedAdjust;
        try c.AdjustBetAmounts(amount) { revertedAdjust = false; } catch { revertedAdjust = true; }
        assert(revertedOpen == revertedAdjust);
    }
    receive() external payable {}
}

